package com.hugzzbotzx.app;

import android.Manifest;import android.app.*;import android.app.usage.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.Typeface;import android.hardware.camera2.CameraManager;import android.net.ConnectivityManager;import android.net.NetworkCapabilities;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
    int INK=Color.rgb(21,19,42), PAPER=Color.rgb(255,253,248), VIOLET=Color.rgb(109,74,255), PINK=Color.rgb(255,79,163), CYAN=Color.rgb(25,200,255), YELLOW=Color.rgb(255,216,77), MINT=Color.rgb(57,217,164), LAV=Color.rgb(238,232,255), PEACH=Color.rgb(255,229,212), SKY=Color.rgb(221,246,255), RED=Color.rgb(255,77,109);
    LinearLayout root,content; TextView title,subtitle; Handler handler=new Handler(Looper.getMainLooper()); boolean flash=false, sos=false; CameraManager camera; String camId;
    android.content.SharedPreferences prefs;
    @Override public void onCreate(Bundle b){super.onCreate(b); prefs=getSharedPreferences("v6",0); camera=(CameraManager)getSystemService(CAMERA_SERVICE); build(); showHome();}
    TextView tv(String s,float sp){TextView t=new TextView(this);t.setText(s);t.setTextColor(INK);t.setTextSize(sp);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(4,4,4,4);return t;}
    Button btn(String s,int bg){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(12);b.setAllCaps(false);b.setBackgroundResource(bg==PINK?R.drawable.button_pink:R.drawable.button);b.setText(s);return b;}
    LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);return r;}
    LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(18,16,18,16);c.setBackgroundResource(R.drawable.panel);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,16);c.setLayoutParams(p);return c;}
    void build(){
      root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(PAPER);
      LinearLayout head=row();head.setPadding(14,10,14,6);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.hugzzbotzx_logo);head.addView(logo,new LinearLayout.LayoutParams(58,58));
      LinearLayout ht=new LinearLayout(this);ht.setOrientation(LinearLayout.VERTICAL);title=tv("HUGZZBOTZX",23);subtitle=tv("COMIC COMMAND • V6.0",11);subtitle.setTextColor(VIOLET);ht.addView(title);ht.addView(subtitle);head.addView(ht,new LinearLayout.LayoutParams(0,-2,1));
      TextView badge=tv("V6",13);badge.setTextColor(Color.WHITE);badge.setGravity(Gravity.CENTER);badge.setBackgroundColor(PINK);head.addView(badge,new LinearLayout.LayoutParams(48,42));root.addView(head);
      ScrollView sv=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(16,8,16,90);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));
      LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(INK);nav.setPadding(6,6,6,6);String[] ns={"HOME","DEVICES","TOOLS","FAMILY","LOGS","MORE"};for(String n:ns){Button q=new Button(this);q.setText(n);q.setTextSize(10);q.setTextColor(Color.WHITE);q.setAllCaps(false);q.setBackgroundColor(Color.TRANSPARENT);q.setOnClickListener(v->{if(n.equals("HOME"))showHome();else if(n.equals("DEVICES"))showDevices();else if(n.equals("TOOLS"))showTools();else if(n.equals("FAMILY"))showFamily();else if(n.equals("LOGS"))showLogs();else showMore();});nav.addView(q,new LinearLayout.LayoutParams(0,58,1));}root.addView(nav);setContentView(root);
    }
    void clear(){content.removeAllViews();}
    void comic(String text,int color){TextView t=tv("★ "+text,15);t.setTextColor(INK);t.setBackgroundColor(color);t.setPadding(18,14,18,14);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,14);content.addView(t,p);}
    void addCard(String head,String body,int tint){LinearLayout c=card();c.setBackgroundColor(tint);TextView h=tv(head,18);TextView b=tv(body,12);b.setTypeface(Typeface.DEFAULT,Typeface.NORMAL);b.setPadding(0,8,0,8);c.addView(h);c.addView(b);content.addView(c);}
    void showHome(){clear();comic("WELCOME, OPERATOR! Your phone is the lab. Your family stays in control.",YELLOW);addCard("DEVICE PULSE",deviceSummary(),SKY);LinearLayout r=row();Button diag=btn("RUN DIAGNOSTIC",VIOLET);Button report=btn("SHARE REPORT",PINK);r.addView(diag,new LinearLayout.LayoutParams(0,58,1));r.addView(report,new LinearLayout.LayoutParams(0,58,1));content.addView(r);diag.setOnClickListener(v->{log("Diagnostic scan");showDiagnostics();});report.setOnClickListener(v->shareReport());addCard("SAFE ACCESS", "• ADB: user-authorized pairing only\n• Remote support: visible session + stop button\n• Bug Lab: local test device/emulator only",LAV);}
    String deviceSummary(){Runtime rt=Runtime.getRuntime();long free=rt.freeMemory()/1048576,total=rt.totalMemory()/1048576;String net=network();return "Android "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")\nRAM app heap: "+free+" MB free / "+total+" MB\nNetwork: "+net+"\nModel: "+Build.MANUFACTURER+" "+Build.MODEL;}
    String network(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);NetworkCapabilities n=cm.getNetworkCapabilities(cm.getActiveNetwork());if(n==null)return "OFFLINE";if(n.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))return "Wi‑Fi";if(n.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR))return "Mobile data";return "Connected";}
    void showDevices(){clear();comic("DEVICE PANEL — connect only after the other device authorizes the session.",CYAN);addCard("WIRELESS ADB", "Android 11+ → Developer options → Wireless debugging → Pair device with pairing code.\nHugzzBotzX does not silently enable ADB.",SKY);Button pair=btn("OPEN WIRELESS DEBUGGING",VIOLET);content.addView(pair);pair.setOnClickListener(v->{try{startActivity(new Intent(Settings.ACTION_WIRELESS_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});Button code=btn("GENERATE PAIRING NOTE",PINK);content.addView(code);code.setOnClickListener(v->{String x=String.valueOf(100000+new Random().nextInt(900000));copy(x);toast("Pairing note copied: "+x);log("Generated pairing note");});addCard("CONNECTED DEVICES", "This V6 build intentionally shows an authorization-first workflow. A real remote session needs a trusted backend and explicit approval on the target device.",LAV);}
    void showTools(){clear();comic("TOOLS — REAL LOCAL ACCESS, SAFE TESTS, ZERO STEALTH.",PEACH);Button f=btn("FLASHLIGHT ON / OFF",VIOLET);content.addView(f);f.setOnClickListener(v->toggleFlash());Button s=btn("SOS FLASH • 10 SEC",PINK);content.addView(s);s.setOnClickListener(v->startSos());Button u=btn("APP USAGE / SCREEN TIME",VIOLET);content.addView(u);u.setOnClickListener(v->{try{startActivity(new Intent(Settings.ACTION_USAGE_ACCESS_SETTINGS));}catch(Exception e){}});Button apps=btn("APP INVENTORY",PINK);content.addView(apps);apps.setOnClickListener(v->showApps());Button lab=btn("OPEN BUG LAB",VIOLET);content.addView(lab);lab.setOnClickListener(v->showLab());addCard("DIAGNOSTICS", "Battery, storage, memory, network and installed-package inventory are read from Android APIs. Sensitive actions stay behind Android permissions.",LAV);}
    void toggleFlash(){if(Build.VERSION.SDK_INT<23){toast("Flashlight API unavailable");return;}if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},42);toast("Allow camera access, then tap again.");return;}try{if(camId==null){for(String id:camera.getCameraIdList()){android.hardware.camera2.CameraCharacteristics c=camera.getCameraCharacteristics(id);Boolean f=c.get(android.hardware.camera2.CameraCharacteristics.FLASH_INFO_AVAILABLE);Integer l=c.get(android.hardware.camera2.CameraCharacteristics.LENS_FACING);if(Boolean.TRUE.equals(f)&&Integer.valueOf(android.hardware.camera2.CameraCharacteristics.LENS_FACING_BACK).equals(l)){camId=id;break;}}}if(camId==null){toast("No flashlight found");return;}flash=!flash;camera.setTorchMode(camId,flash);log("Flashlight "+(flash?"ON":"OFF"));toast(flash?"FLASH ON":"FLASH OFF");}catch(Exception e){toast("Camera permission needed");requestPermissions(new String[]{Manifest.permission.CAMERA},42);}}
    void startSos(){if(sos)return;if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA},42);toast("Allow camera access, then tap SOS again.");return;}sos=true;log("SOS flash started");final long end=System.currentTimeMillis()+10000;Runnable r=new Runnable(){public void run(){if(!sos||System.currentTimeMillis()>=end){sos=false;try{if(flash){camera.setTorchMode(camId,false);flash=false;}}catch(Exception e){}toast("SOS finished");return;}toggleFlash();handler.postDelayed(this,650);}};handler.post(r);}
    void showFamily(){clear();comic("FAMILY HQ — rules should be agreed together, not hidden.",PINK);addCard("PARENT PIN", "Protect local settings with a PIN. This is not a bypass for Android security.",LAV);Button pin=btn("SET / CHANGE PIN",VIOLET);content.addView(pin);pin.setOnClickListener(v->setPin());addCard("ROUTINES", "Study 16:00–18:00\nSleep 21:00–06:00\nFocus 25 minutes\nThese are local planning rules and reminders.",SKY);Button wb=btn("OPEN DIGITAL WELLBEING",PINK);content.addView(wb);wb.setOnClickListener(v->{try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception e){}});addCard("EMERGENCY", "Emergency contact opens the normal Android dialer; it never calls silently.",PEACH);Button call=btn("OPEN DIALER",VIOLET);content.addView(call);call.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL)));}
    void setPin(){final EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setHint("4–8 digits");new AlertDialog.Builder(this).setTitle("Parent PIN").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{String x=e.getText().toString();if(x.length()>=4&&x.length()<=8){prefs.edit().putString("pin",x).apply();log("Parent PIN updated");toast("PIN saved locally");}else toast("PIN must be 4–8 digits");}).show();}
    void showLogs(){clear();comic("LOGBOOK — every local action leaves a small trace.",YELLOW);String s=prefs.getString("logs","");if(s.isEmpty())s="No activity yet.";addCard("RECENT EVENTS",s,LAV);Button clear=btn("CLEAR LOG",PINK);content.addView(clear);clear.setOnClickListener(v->{prefs.edit().remove("logs").apply();showLogs();});Button share=btn("EXPORT LOG",VIOLET);content.addView(share);share.setOnClickListener(v->shareReport());}
    void showMore(){clear();comic("MORE — diagnostics, permissions and about.",MINT);Button d=btn("DEVICE DIAGNOSTICS",VIOLET);content.addView(d);d.setOnClickListener(v->showDiagnostics());Button p=btn("APP PERMISSIONS",PINK);content.addView(p);p.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));Button a=btn("ABOUT HUGZZBOTZX",VIOLET);content.addView(a);a.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("HugzzBotzX V6.0").setMessage("Comic Command Edition\nAuthorized diagnostics • family tools • safe bug lab\n\nNo stealth control or destructive payloads.").setPositiveButton("OK",null).show());}
    void showDiagnostics(){clear();comic("SCAN COMPLETE — local device snapshot.",CYAN);addCard("SYSTEM",deviceSummary(),SKY);addCard("STORAGE",storage(),LAV);addCard("BATTERY",battery(),PEACH);addCard("PACKAGES",packageCount()+" installed packages visible to PackageManager.",MINT);Button sh=btn("SHARE SNAPSHOT",PINK);content.addView(sh);sh.setOnClickListener(v->shareReport());}
    String storage(){android.os.StatFs s=new android.os.StatFs(Environment.getDataDirectory().getPath());long free=s.getAvailableBytes()/1073741824,total=s.getTotalBytes()/1073741824;return free+" GB free / "+total+" GB total";}
    String battery(){Intent i=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int l=i==null? -1:i.getIntExtra("level",-1);int sc=i==null?100:i.getIntExtra("scale",100);return l<0?"Unknown":Math.round(l*100f/sc)+"%";}
    int packageCount(){try{return getPackageManager().getInstalledPackages(0).size();}catch(Exception e){return 0;}}
    void showApps(){clear();comic("APP INVENTORY — package names only; no hidden data collection.",YELLOW);List<PackageInfo> ps=getPackageManager().getInstalledPackages(0);int n=0;for(PackageInfo p:ps){if(n++>80)break;TextView t=tv(p.applicationInfo.loadLabel(getPackageManager())+"\n"+p.packageName,12);t.setTypeface(Typeface.DEFAULT,Typeface.NORMAL);t.setPadding(12,12,12,12);t.setBackgroundResource(R.drawable.panel_violet);content.addView(t,new LinearLayout.LayoutParams(-1,-2));}}
    void showLab(){clear();comic("BUG LAB — controlled tests on THIS device or emulator only.",PEACH);Button cpu=btn("CPU TEST • 2 SEC",VIOLET);content.addView(cpu);cpu.setOnClickListener(v->{long st=System.nanoTime();long x=0;while((System.nanoTime()-st)<2_000_000_000L){x=x*1664525L+1013904223L;}toast("CPU test complete: "+Long.toHexString(x));log("CPU micro-test completed");});Button mem=btn("MEMORY TEST • 4 MB",PINK);content.addView(mem);mem.setOnClickListener(v->{byte[] a=new byte[4*1024*1024];for(int i=0;i<a.length;i+=4096)a[i]=(byte)i;toast("4 MB allocation test complete");log("Memory test completed");});Button crash=btn("EXCEPTION DEMO (CAUGHT)",VIOLET);content.addView(crash);crash.setOnClickListener(v->{try{throw new RuntimeException("Demo exception");}catch(Exception e){toast("Demo exception caught safely");log("Exception demo handled");}});addCard("BOUNDARIES","No remote crash, flood, exploit, bootloop or destructive payloads. Tests stop automatically.",LAV);}
    void log(String s){String old=prefs.getString("logs","");String line=new SimpleDateFormat("HH:mm:ss",Locale.getDefault()).format(new Date())+"  •  "+s;String out=(line+"\n"+old);if(out.length()>6000)out=out.substring(0,6000);prefs.edit().putString("logs",out).apply();}
    void copy(String s){((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("HugzzBotzX",s));}
    void shareReport(){String r="HugzzBotzX V6.0\n"+new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(new Date())+"\n\n"+deviceSummary()+"\nStorage: "+storage()+"\nBattery: "+battery()+"\nLogs:\n"+prefs.getString("logs","none");Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,r);startActivity(Intent.createChooser(i,"Share diagnostic report"));}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}
